    for cr in range(rows):
        new_row = [3] * cols
        col_pos = 0

        for obj_id in order:
            if obj_id == 7:
                h, w = 7, 5
            elif obj_id == 9:
                h, w = 5, 4
            elif obj_id == 4:
                h, w = 4, 4
            else:
                continue

            if cr < h:
                for c in range(col_pos, min(col_pos + w, cols)):
                    new_row[c] = obj_id
                col_pos += w

        output.append(new_row)
    return output

print("All orderings:")
for perm in itertools.permutations([7, 9, 4]):
    output = make_contiguous(perm)
    # Check first 4 rows show all colors
    has_all = set(output[0]) == {3, 7, 9, 4}
    print(f"  Order {perm}: row0 has all colors = {has_all}")
